using Godot;
using Arconist.Core;
using System.Text.Json;
namespace Arconist.GodotApp;
// Production-node/resource mathematical tests, headless only. Never OS input.
public static class ArcValidation
{
 public static void Run(Node owner,SpatialTrack track,string evidenceDir)
 {
  int passed=0,failed=0;var outcomes=new List<object>();
  void Check(bool ok,string why){if(!ok)throw new Exception(why);}
  void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});GD.Print("PASS R007 "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});GD.Print("FAIL R007 "+name+": "+e.Message);}}
  string Load(string name)=>Godot.FileAccess.GetFileAsString("res://content/"+name);
  Kernel New(){var k=new Kernel(Chart.Parse(Load("native_moving_arc.aff")));k.Frame(0);k.Frame(3002);return k;}
  void F(Kernel k,int e)=>k.Frame(e+3002);
  Test("ten preserved and new chart resources accessible",()=>{foreach(string n in new[]{"practice.aff","ordinary_two_tap.aff","mixed_practice.aff","native_hold.aff","hold_first.aff","tap_first.aff","audible_practice.aff","audible_aff120.aff","sky_practice.aff","native_moving_arc.aff"})Check(Chart.Parse(Load(n)).JudgmentUnits>0,n);});
  Test("real segmented arc mesh and target marker",()=>{var k=New();F(k,1000);track.Refresh(k);Check(track.ArcVisualCount==1&&track.ArcTarget(k.Arcs[0].Id)!.Mesh is BoxMesh&&track.ArcVisual(k.Arcs[0].Id)!.GetChildren().OfType<MeshInstance3D>().Count()>=12,"real mesh nodes");});
  Test("core cache controls target and rendering never judges",()=>{var k=New();F(k,1250);track.Refresh(k);var a=k.Arcs[0];Check(track.ArcTarget(a.Id)!.Position.IsEqualApprox(SpatialTrack.World(a.TargetX,a.TargetY,0)),"cache position");string State()=>JsonSerializer.Serialize(new{k.Score,k.Health,k.ContactCount,a.Color,a.Records,a.Cache});string before=State();for(int i=0;i<20;i++)track.Refresh(k);Check(before==State(),"read-only renderer");});
  Test("sky intersection is Z0 while ground remains Y0",()=>{Check(SpatialTrack.SkyIntersection(new Vector3(0,2,3),new Vector3(1,-1,-1),out var sky)&&sky.Z==0&&sky.X==3,"sky plane");Check(SpatialTrack.GroundIntersection(new Vector3(0,2,3),new Vector3(1,-1,-1),out var ground)&&ground.Y==0&&ground.X==2,"ground plane");});
  Test("degenerate backwards and nonfinite sky rays rejected",()=>{Check(!SpatialTrack.SkyIntersection(Vector3.One,Vector3.Up,out _)&&!SpatialTrack.SkyIntersection(Vector3.One,Vector3.Back,out _)&&!SpatialTrack.SkyIntersection(new Vector3(float.NaN,0,1),Vector3.Forward,out _),"safe rays");});
  Test("actual perspective sky roundtrip default and alternate camera",()=>{var k=New();F(k,1375);var a=k.Arcs[0];foreach(bool alternate in new[]{false,true}){track.SetView(alternate);var world=SpatialTrack.World(a.TargetX,a.TargetY,0);var screen=track.Camera.UnprojectPosition(world);Check(track.PickSky(screen,out var point),"inside viewport");Check(Math.Abs(point.Point.X-a.TargetX)<0.001&&Math.Abs(point.Point.Y-a.TargetY)<0.001&&ArcSpatial.Matches(a.TargetX,a.TargetY,point),"camera ray mapping");}track.SetView(false);});
  Test("changed viewport ray mapping and outside rejection",()=>{var vp=(SubViewport)track.GetViewport();var previous=vp.Size;var container=(SubViewportContainer)vp.GetParent();bool stretch=container.Stretch;container.Stretch=false;try{foreach(var size in new[]{new Vector2I(610,550),new Vector2I(732,660)}){vp.Size=size;Check(vp.Size==size,"actual changed viewport size");var screen=track.Camera.UnprojectPosition(SpatialTrack.World(212,300,0));Check(track.PickSky(screen,out var point)&&Math.Abs(point.Point.X-212)<0.001,"resize mapping");Check(!track.PickSky(new Vector2(-1,10),out _)&&!track.PickSky(new Vector2(size.X+1,size.Y),out _)&&!track.PickSky(new Vector2(float.NaN,0),out _),"outside");}}finally{vp.Size=previous;container.Stretch=stretch;}});
  Test("entire practice trajectory visible and projectable in both views",()=>{var k=new Kernel(Chart.Parse(Load("sky_practice.aff")));k.Frame(0);k.Frame(3002);foreach(int e in new[]{4000,6000,8000,10000,12000}){F(k,e);var a=k.Arcs[0];foreach(bool alternate in new[]{false,true}){track.SetView(alternate);var screen=track.Camera.UnprojectPosition(SpatialTrack.World(a.TargetX,a.TargetY,0));Check(track.PickSky(screen,out var point)&&ArcSpatial.Matches(a.TargetX,a.TargetY,point),$"trajectory E{e} view{alternate}");}}track.SetView(false);});
  Test("actual camera contact activates core and feedback",()=>{var k=New();F(k,1000);var a=k.Arcs[0];var screen=track.Camera.UnprojectPosition(SpatialTrack.World(a.TargetX,a.TargetY,0));Check(track.PickSky(screen,out var point),"ray");k.DownSpatial(4002,42,0,point);F(k,1125);track.Refresh(k);Check(a.Holding&&k.Pure==1&&((StandardMaterial3D)track.ArcTarget(a.Id)!.MaterialOverride).AlbedoColor==new Color("a5f56d"),"accepted indicator");});
  Test("checkpoint marker reflects authoritative resolved state",()=>{var k=New();F(k,1000);var a=k.Arcs[0];k.DownSpatial(4002,42,0,new SkyContact(new SkyPoint(a.TargetX,a.TargetY,0)));F(k,1125);track.Refresh(k);var marker=track.ArcVisual(a.Id)!.GetNode<MeshInstance3D>("Checkpoint1250");Check(a.Records[0].Resolved&&marker.Visible&&((StandardMaterial3D)marker.MaterialOverride).AlbedoColor==new Color("a5f56d"),"checkpoint feedback");});
  Test("arc pause keeps cache and node at frozen time",()=>{var k=New();F(k,1200);track.Refresh(k);var node=track.ArcTarget(k.Arcs[0].Id)!;var p=node.Position;k.Pause(4202);F(k,61200);track.Refresh(k);Check(k.Timeline.EffectiveTime==1200&&node.Position==p&&k.Pure==0,"freeze");k.Resume(64202);k.Frame(64203);track.Refresh(k);Check(node.Position!=p,"next frame movement");});
  Test("restart and menu remove old arc nodes",()=>{var k=New();track.Refresh(k);var old=track.ArcVisual(k.Arcs[0].Id)!;var next=New();track.Refresh(next);Check(!old.IsInsideTree()&&!ReferenceEquals(old,track.ArcVisual(next.Arcs[0].Id)),"replace");track.Refresh(null);Check(track.ArcVisualCount==0,"menu");});
  Test("completion hides arc and moving-to-results is integration",()=>{var k=New();for(int e=1;e<=2501;e++){F(k,e);var a=k.Arcs[0];if(e==1000)k.DownSpatial(e+3002,42,0,new SkyContact(new SkyPoint(a.TargetX,a.TargetY,0)));else if(e>1000&&e<=2000)k.MoveSpatial(42,0,new SkyContact(new SkyPoint(a.TargetX,a.TargetY,0)));}track.Refresh(k);Check(k.Result!.Score==10000003&&!track.ArcVisual(k.Arcs[0].Id)!.Visible,"result hide");});
  track.Refresh(null);track.SetView(false);
  File.WriteAllText(Path.Combine(evidenceDir,"arc-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,humanQualification="PENDING"},new JsonSerializerOptions{WriteIndented=true}));GD.Print($"R007 headless: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");owner.GetTree().Quit(failed==0?0:1);
 }
}
